css:
/* Gruvware — dark appearance only. Light colors come from the theme palette. */
:root.dark {
  --gruvware-ink: #e6d5ae;
  --gruvware-orange: #eead83;
  --gruvware-green: #bac584;
  --gruvware-red: #de9880;
  --gruvware-teal: #7daea3;
}

/* Markdown in chat and file previews. */
:root.dark .chat-markdown :is(a, .chat-markdown-file-link) {
  --context-chip-ink: var(--gruvware-teal);
  color: var(--gruvware-teal);
}
:root.dark .chat-markdown :not(pre) > code { color: var(--gruvware-green); }
:root.dark .chat-markdown li::marker { color: var(--gruvware-orange); }
:root.dark .chat-markdown h1 { color: #d4a599; }
:root.dark .chat-markdown h2 { color: var(--gruvware-orange); }
:root.dark .chat-markdown h3 { color: var(--gruvware-red); }
:root.dark .chat-markdown :is(h4, h5, h6) { color: #d6b37b; }

/* Grouped project names, side-chat titles, and PR list titles. */
:root.dark [data-testid="sidebar-project-folder"] span[class~="text-sidebar-foreground/90"],
:root.dark [data-side-chat-pane] > div:first-child > span.truncate,
:root.dark [data-pull-request-key] span.min-w-0.truncate.text-sm {
  color: var(--gruvware-ink);
}

/* Workspace titlebar controls; leave disabled controls dimmed. */
:root.dark [data-workspace-titlebar-controls]
  :is([data-slot="toggle"], [data-slot="tooltip-trigger"]):not(:disabled, [aria-disabled="true"]) {
  --control-icon-color: var(--gruvware-ink);
  color: var(--gruvware-ink);
}

/* Working / Setting up / Goal, and Done. Leave the snooze wake time alone. */
:root.dark [data-thread-item] span.inline-flex.text-info-foreground:not(.tabular-nums) {
  color: var(--gruvware-orange);
}
:root.dark [data-thread-item] span.inline-flex.text-success-foreground {
  color: var(--gruvware-green);
}

/* Project monograms. The stock SVG carries the color as a utility class. */
:root.dark [data-slot="project-monogram"] svg[class~="dark:text-gray-400"] { color: #bdae93; }
:root.dark [data-slot="project-monogram"] svg:is(
  [class~="dark:text-red-400"], [class~="dark:text-pink-400"], [class~="dark:text-rose-400"]
) { color: var(--gruvware-red); }
:root.dark [data-slot="project-monogram"] svg[class~="dark:text-orange-400"] { color: var(--gruvware-orange); }
:root.dark [data-slot="project-monogram"] svg[class~="dark:text-amber-400"] { color: #ca9a70; }
:root.dark [data-slot="project-monogram"] svg[class~="dark:text-yellow-400"] { color: #d6b37b; }
:root.dark [data-slot="project-monogram"] svg:is(
  [class~="dark:text-lime-400"], [class~="dark:text-green-400"]
) { color: var(--gruvware-green); }
:root.dark [data-slot="project-monogram"] svg:is(
  [class~="dark:text-emerald-400"], [class~="dark:text-teal-400"], [class~="dark:text-cyan-400"]
) { color: #b2ba8e; }
:root.dark [data-slot="project-monogram"] svg:is(
  [class~="dark:text-sky-400"], [class~="dark:text-blue-400"], [class~="dark:text-indigo-400"]
) { color: #adb79d; }
:root.dark [data-slot="project-monogram"] svg:is(
  [class~="dark:text-violet-400"], [class~="dark:text-purple-400"], [class~="dark:text-fuchsia-400"]
) { color: #d4a599; }

/* Inherited diff and file-tree colors. Respect the Blue–Orange diff setting. */
:root.dark:not([data-diff-color-scheme="blue-orange"]) {
  --diff-addition-foreground: var(--gruvware-green);
  --diff-deletion-foreground: var(--gruvware-red);
  --diff-added-icon: var(--diff-addition-foreground);
  --diff-modified-icon: var(--gruvware-teal);
  --diffs-addition-color-override: var(--diff-addition-foreground);
  --diffs-deletion-color-override: var(--diff-deletion-foreground);
  --diffs-modified-color-override: var(--gruvware-teal);
  --trees-status-added-override: var(--diff-addition-foreground);
  --trees-status-untracked-override: var(--diff-addition-foreground);
  --trees-status-deleted-override: var(--diff-deletion-foreground);
  --trees-status-modified-override: var(--gruvware-teal);
}

/* File tree hover background and selected-row text. */
:root.dark file-tree-container {
  --trees-bg-muted-override: #2a2928;
  --trees-selected-fg-override: var(--contrast-foreground);
}

/* Dark diff backgrounds. Leave the Blue–Orange preset alone. */
:root.dark:not([data-diff-color-scheme="blue-orange"]) diffs-container {
  --diff-addition: #bac584;
  --diff-deletion: #de9880;
}
